export const isArbStackChain = (chainName: ChainName): boolean => {
    return [
        // Confirmed by `GetArbChains` workflow.
        ChainName.ANIMECHAIN,
        ChainName.APE,
        ChainName.ARBITRUM,
        ChainName.ARBSEP,
        ChainName.CURTIS,
        ChainName.DEGEN,
        ChainName.EDU,
        ChainName.ETHEREAL,
        ChainName.GRAVITY,
        ChainName.HUMANITY,
        ChainName.MP1,
        ChainName.NOVA,
        ChainName.OPENCAMPUS,
        ChainName.PLUME4,
        ChainName.PLUMEPHOENIX,
        ChainName.RARIBLE,
        ChainName.REYA,
        ChainName.ROBINHOOD,
        ChainName.SANKO,
        ChainName.SUPERPOSITION,
        ChainName.XAI,
        ChainName.ZAMA,
        // Unreachable in mainnet and testnet.
        ChainName.BB1,
        ChainName.BL2,
        ChainName.CONVERGE,
        ChainName.EBI,
        ChainName.ETHEREAL2,
        ChainName.OLIVE,
        ChainName.PLUME,
        ChainName.PLUME2,
        ChainName.REAL,
        ChainName.TREASURE,
        ChainName.UNREAL,
        ChainName.XCHAIN,
    ].includes(chainName);
};

export const isZkChain = (chainName: ChainName): boolean => {
    return [
        // Confirmed by `GetZkChains` workflow.
        ChainName.ABSTRACT,
        ChainName.CRONOSZKEVM,
        ChainName.LENS,
        ChainName.SOPHON,
        ChainName.ZKLINK,
        ChainName.ZKSYNC,
        ChainName.ZKSYNCSEP,
        // Unreachable in mainnet and testnet.
        ChainName.TREASURE,
    ].includes(chainName);
};

export const isAltChain = (chainName: ChainName): boolean => {
    return [
        // Native gas token is DAI (ERC20); confirmed via on-chain EndpointV2.nativeToken()
        // and the earlier static-config gasTokenAddress fields.
        ChainName.ANUBIS,
        // Confirmed by `GetAltChains` workflow.
        ChainName.DINARI,
        ChainName.MODERATO,
        ChainName.SAGAEVM,
        ChainName.SKALE,
        ChainName.SPACE,
        ChainName.TEMPO,
        // Unreachable in mainnet and testnet.
        ChainName.TEMPODEV1,
    ].includes(chainName);
};
